                        for field in ["name", "description", "rationale"]:
                            if field not in dim:
                                issues.append(f"[WARN] 维度 #{i} 缺少 '{field}' 字段")

            # 检查 domain 字段
            if "domain" not in analysis:
                issues.append("[WARN] 'input_analysis' 缺少 'domain' 字段")

            # 检查 input_summary
            if "input_summary" not in analysis:
                issues.append("[WARN] 'input_analysis' 缺少 'input_summary' 字段")

    # 检查 facts（与 task1 类似，但 category 使用自设计维度名称）
    if "facts" in data:
        facts = data["facts"]
        if not isinstance(facts, list):
            issues.append("[ERROR] 'facts' 应为列表")
        elif len(facts) == 0:
            issues.append("[WARN] 事实表为空")
        else:
            for i, fact in enumerate(facts):
                if "category" not in fact:
                    issues.append(f"[WARN] 事实 #{i} 缺少 'category' 字段")

    # 检查 report
    if "report" in data:
        report = data["report"]
        if isinstance(report, dict):
            if "sectioned_analysis" in report and isinstance(report["sectioned_analysis"], list):
                for i, section in enumerate(report["sectioned_analysis"]):
                    if "dimension" not in section:
                        issues.append(f"[WARN] 报告章节 #{i} 缺少 'dimension' 字段")

    # 检查 self_assessment
    if "self_assessment" in data:
        sa = data["self_assessment"]
        if not isinstance(sa, dict):
            issues.append("[ERROR] 'self_assessment' 应为字典")
        else:
            # 检查评分字段
            score_fields = ["dimension_design_quality", "fact_extraction_coverage",
                           "report_coherence", "overall_score"]
            for field in score_fields:
                if field not in sa:
                    issues.append(f"[WARN] 'self_assessment' 缺少 '{field}' 字段")
                elif isinstance(sa.get(field), (int, float)):
                    if sa[field] < 0.0 or sa[field] > 1.0:
                        issues.append(f"[WARN] '{field}' 评分 {sa[field]} 超出 [0.0, 1.0] 范围")

            # 检查局限性描述
            if "known_limitations" not in sa:
                issues.append("[WARN] 'self_assessment' 缺少 'known_limitations' 字段（建议诚实地列出局限性）")
            if "improvement_suggestions" not in sa:
                issues.append("[WARN] 'self_assessment' 缺少 'improvement_suggestions' 字段")

    return issues


def check_report_md(report_path: str) -> list[str]:
    """检查 REPORT.md 的基本结构"""
